window.docContents[61].resolve({"/Installation-and-Setup/#Statlib--Installation-and-Setup--Installing-Statlib":{"contents":"The Statlib source is available at\ngithub.com/stat-lib/statlib.\n\nClone the repository and create a working branch:\n\ngit clone https://github.com/stat-lib/statlib.git\ncd statlib\ngit checkout -b my-statlib-branch\n\n\nBuild the Lean library:\n\nlake exe cache get\nlake build\n\n\nYou can then import Statlib from Lean files:\n\nimport Statlib\nimport Statlib.Inference\n\n\n","context":"Statlib\u0009Installation and Setup","header":"1.2. Installing Statlib","id":"/Installation-and-Setup/#Statlib--Installation-and-Setup--Installing-Statlib"}});